const root = $json ?? {};
const body = root.body && typeof root.body === "object" && !Array.isArray(root.body)
  ? root.body
  : {};

function readText(value) {
  if (value === null || value === undefined) return "";
  if (typeof value === "object") return "";
  return String(value).trim();
}

function normalizeLanguageCode(value) {
  const lowered = readText(value).toLowerCase();
  if (lowered.startsWith("fr")) return "fr";
  if (lowered.startsWith("en")) return "en";
  if (lowered.startsWith("es")) return "es";
  if (lowered.startsWith("de")) return "de";
  if (lowered.startsWith("it")) return "it";
  if (lowered.startsWith("pt")) return "pt";
  return "en";
}

function normalizeScanLabel(value) {
  const raw = readText(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (!raw) return null;

  const aliases = {
    face: "face",
    visage: "face",
    "face scan": "face",
    facial: "face",
    skin: "face",
    "skin face": "face",
    body: "body",
    corps: "body",
    "body scan": "body",
    physique: "body",
    silhouette: "body",
    fitness: "body",
    nutrition: "nutrition",
    meal: "nutrition",
    food: "nutrition",
    fridge: "nutrition",
    chef: "nutrition",
    "nutrition scan": "nutrition",
    plate: "nutrition",
    repas: "nutrition",
  };

  return aliases[raw] ?? null;
}

function normalizeLegacyAppScanType(value) {
  const raw = readText(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (raw === "health") return "face";
  if (raw === "body") return "body";
  if (raw === "nutrition") return "nutrition";
  return null;
}

function resolveRequestedScanType() {
  const candidates = [
    { value: body.expected_scan_type, legacyAppType: false },
    { value: body.scan_type, legacyAppType: false },
    { value: body.analysis_type, legacyAppType: false },
    { value: body.type, legacyAppType: false },
    { value: body.scanType, legacyAppType: true },
    { value: root.expected_scan_type, legacyAppType: false },
    { value: root.scan_type, legacyAppType: false },
    { value: root.analysis_type, legacyAppType: false },
    { value: root.type, legacyAppType: false },
    { value: root.scanType, legacyAppType: true },
  ];

  for (const candidate of candidates) {
    const normalized = candidate.legacyAppType
      ? normalizeLegacyAppScanType(candidate.value)
      : normalizeScanLabel(candidate.value);
    if (normalized) {
      return normalized;
    }
  }

  return null;
}

const language_code = normalizeLanguageCode(
  body.language || body.locale || root.language || root.locale,
);
const requested_scan_type = resolveRequestedScanType();
const scan_route = requested_scan_type ?? "auto_detect_fallback";

return [
  {
    json: {
      ...root,
      language_code,
      requested_scan_type,
      scan_route,
    },
  },
];

const root = $json ?? {};
const body = root.body && typeof root.body === "object" && !Array.isArray(root.body)
  ? { ...root.body }
  : undefined;

if (body && Object.prototype.hasOwnProperty.call(body, "imageBase64")) {
  delete body.imageBase64;
}

return [
  {
    json: {
      ...root,
      ...(body ? { body } : {}),
    },
  },
];

const allowedRoutes = new Set(["face", "body", "nutrition"]);
const currentRoute = typeof $json?.scan_route === "string"
  ? $json.scan_route.trim().toLowerCase()
  : "";
const scan_route = allowedRoutes.has(currentRoute)
  ? currentRoute
  : "auto_detect_fallback";
const binary = $input?.item?.binary ?? $binary ?? undefined;

return [
  {
    json: {
      ...$json,
      scan_route,
    },
    ...(binary ? { binary } : {}),
  },
];

// Final shared analyse_1 normalizer.
// Every specialized branch must converge here so the front-end always receives the same contract:
// { success: boolean, data: object } with only face, body, nutrition, or error.

function isPlainObject(value) {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function readText(value) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
}

function normalizeLanguageCode(value) {
  const lowered = String(value ?? "").trim().toLowerCase();
  if (lowered.startsWith("fr")) return "fr";
  if (lowered.startsWith("en")) return "en";
  if (lowered.startsWith("de")) return "de";
  if (lowered.startsWith("it")) return "it";
  if (lowered.startsWith("es")) return "es";
  if (lowered.startsWith("pt")) return "pt";
  return "en";
}

function normalizeScanType(value) {
  const textValue = readText(value);
  return textValue ? textValue.toLowerCase() : null;
}

function normalizeExpectedRoute(value) {
  const route = normalizeScanType(value);
  return route === "face" || route === "body" || route === "nutrition"
    ? route
    : null;
}

const languageCode = normalizeLanguageCode(
  $json?.language_code ??
    (isPlainObject($json?.body) ? $json.body.language ?? $json.body.locale : null) ??
    $json?.language ??
    $json?.locale,
);

const LOCALIZED_MESSAGES = {
  invalid_scan_response: {
    fr: "Reponse du scan invalide.",
    en: "Invalid scan response.",
    de: "Ungueltige Scan-Antwort.",
    it: "Risposta della scansione non valida.",
    es: "Respuesta de escaneo no valida.",
    pt: "Resposta de escaneamento invalida.",
  },
  generic_analysis_error: {
    fr: "Analyse impossible. Veuillez reessayer.",
    en: "Unable to analyze the image. Please try again.",
    de: "Bild konnte nicht analysiert werden. Bitte versuche es erneut.",
    it: "Impossibile analizzare l'immagine. Riprova.",
    es: "No se puede analizar la imagen. Intentalo de nuevo.",
    pt: "Nao foi possivel analisar a imagem. Tente novamente.",
  },
  scan_type_mismatch: {
    fr: "Le type de scan retourne ne correspond pas a la demande.",
    en: "The returned scan type does not match the requested route.",
    de: "Der zurueckgegebene Scan-Typ passt nicht zur angeforderten Route.",
    it: "Il tipo di scansione restituito non corrisponde al percorso richiesto.",
    es: "El tipo de escaneo devuelto no coincide con la ruta solicitada.",
    pt: "O tipo de escaneamento retornado nao corresponde a rota solicitada.",
  },
};

function getLocalizedMessage(key) {
  const table = LOCALIZED_MESSAGES[key] ?? LOCALIZED_MESSAGES.generic_analysis_error;
  return table[languageCode] ?? table.en ?? "Unknown error.";
}

function stripCodeFences(value) {
  if (typeof value !== "string") return "";
  const trimmed = value.trim();
  if (!trimmed) return "";
  const fence = String.fromCharCode(96).repeat(3);
  return trimmed
    .replace(new RegExp(fence + "(?:json)?\\s*([\\s\\S]*?)\\s*" + fence, "gi"), "$1")
    .trim();
}

function parseScalarNumber(value) {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : null;
  }
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  if (!trimmed) return null;
  const parsed = Number(trimmed);
  return Number.isFinite(parsed) ? parsed : null;
}

function clampNumber(value, min, max) {
  const parsed = parseScalarNumber(value);
  if (parsed === null) return null;
  return Math.min(Math.max(parsed, min), max);
}

function normalizeEnumKey(value, allowed) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim().toLowerCase();
  if (!trimmed) return null;
  return allowed.includes(trimmed) ? trimmed : null;
}

function normalizeEnumArray(value, allowed) {
  if (!Array.isArray(value)) return [];
  const seen = new Set();
  const result = [];
  for (const item of value) {
    const normalized = normalizeEnumKey(item, allowed);
    if (normalized && !seen.has(normalized)) {
      seen.add(normalized);
      result.push(normalized);
    }
  }
  return result;
}

function pickFirstValue(values) {
  for (const value of values) {
    if (value !== undefined && value !== null) {
      return value;
    }
  }
  return null;
}

function scanTextForParsedObjects(text) {
  const results = [];
  for (let start = 0; start < text.length; start += 1) {
    if (text[start] !== "{") continue;

    let depth = 0;
    let inString = false;
    let escaped = false;

    for (let index = start; index < text.length; index += 1) {
      const char = text[index];

      if (inString) {
        if (escaped) {
          escaped = false;
        } else if (char === "\\") {
          escaped = true;
        } else if (char === "\"") {
          inString = false;
        }
        continue;
      }

      if (char === "\"") {
        inString = true;
        continue;
      }

      if (char === "{") {
        depth += 1;
      } else if (char === "}") {
        depth -= 1;
        if (depth === 0) {
          const candidate = text.slice(start, index + 1);
          try {
            results.push(JSON.parse(candidate));
          } catch {}
          break;
        }
      }
    }
  }
  return results;
}

function collectObjectsFromValue(value, depth) {
  if (depth > 6 || value === null || value === undefined) {
    return [];
  }

  if (typeof value === "string") {
    return collectObjectsFromString(value, depth + 1);
  }

  if (Array.isArray(value)) {
    const nested = [];
    for (const entry of value) {
      nested.push(...collectObjectsFromValue(entry, depth + 1));
    }
    return nested;
  }

  if (!isPlainObject(value)) {
    return [];
  }

  const results = [value];
  const wrapperKeys = ["data", "message", "content", "output", "text", "response", "result", "payload"];

  for (const key of wrapperKeys) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      results.push(...collectObjectsFromValue(value[key], depth + 1));
    }
  }

  if (Array.isArray(value.choices)) {
    results.push(...collectObjectsFromValue(value.choices, depth + 1));
  }

  return results;
}

function collectObjectsFromString(value, depth) {
  if (depth > 6) return [];

  const stripped = stripCodeFences(value);
  if (!stripped) return [];

  try {
    const parsed = JSON.parse(stripped);
    const nested = collectObjectsFromValue(parsed, depth + 1);
    if (nested.length > 0) {
      return nested;
    }
  } catch {}

  const extracted = [];
  for (const parsedCandidate of scanTextForParsedObjects(stripped)) {
    extracted.push(...collectObjectsFromValue(parsedCandidate, depth + 1));
  }
  return extracted;
}

const allowedScanTypes = new Set(["face", "body", "nutrition", "error"]);
const allowedLimitationFlags = new Set([
  "blur",
  "low_light",
  "partial_subject",
  "occlusion",
  "portion_uncertain",
]);
const topLevelCandidates = [
  $json?.message?.content,
  $json?.choices?.[0]?.message?.content,
  $json?.content,
  $json?.output,
  $json?.text,
  $json?.response,
  $json?.data,
  $json,
];

let firstObject = null;
let rawObject = null;

candidateLoop:
for (const candidate of topLevelCandidates) {
  if (candidate === undefined || candidate === null) {
    continue;
  }

  const objects = collectObjectsFromValue(candidate, 0);
  for (const objectCandidate of objects) {
    if (!isPlainObject(objectCandidate)) {
      continue;
    }

    if (!firstObject) {
      firstObject = objectCandidate;
    }

    const scanType = normalizeScanType(objectCandidate.scan_type);
    if (scanType && allowedScanTypes.has(scanType)) {
      rawObject = objectCandidate;
      break candidateLoop;
    }
  }
}

if (!rawObject) {
  rawObject = firstObject;
}

function wrapResult(data) {
  return [
    {
      json: {
        success: data.scan_type !== "error",
        data,
      },
    },
  ];
}

function errorResult(messageKey, explicitMessage) {
  const message = readText(explicitMessage) || getLocalizedMessage(messageKey);
  return wrapResult({
    scan_type: "error",
    message,
  });
}

if (!isPlainObject(rawObject)) {
  return errorResult("invalid_scan_response");
}

const scanType = normalizeScanType(rawObject.scan_type);
if (!scanType || !allowedScanTypes.has(scanType)) {
  return errorResult("invalid_scan_response");
}

const requestedRoute = normalizeExpectedRoute($json?.requested_scan_type);
const explicitRoute = normalizeScanType($json?.scan_route) === "auto_detect_fallback"
  ? "auto_detect_fallback"
  : normalizeExpectedRoute($json?.scan_route);
const expectedRoute = explicitRoute || requestedRoute || "auto_detect_fallback";

if (expectedRoute !== "auto_detect_fallback" && scanType !== "error" && scanType !== expectedRoute) {
  return errorResult("scan_type_mismatch");
}

function buildAnalysisMeta(source) {
  const rawMeta = isPlainObject(source.analysis_meta)
    ? source.analysis_meta
    : isPlainObject(source.analysisMeta)
      ? source.analysisMeta
      : {};
  const rawFlags = Array.isArray(rawMeta.limitation_flags)
    ? rawMeta.limitation_flags
    : Array.isArray(rawMeta.limitationFlags)
      ? rawMeta.limitationFlags
      : [];

  return {
    confidence_score: clampNumber(
      pickFirstValue([rawMeta.confidence_score, rawMeta.confidenceScore]),
      0,
      100,
    ),
    image_quality_score: clampNumber(
      pickFirstValue([rawMeta.image_quality_score, rawMeta.imageQualityScore]),
      0,
      100,
    ),
    metric_coverage_score: clampNumber(
      pickFirstValue([rawMeta.metric_coverage_score, rawMeta.metricCoverageScore]),
      0,
      100,
    ),
    limitation_flags: Array.from(
      new Set(
        rawFlags
          .map((item) => readText(item))
          .filter((item) => item && allowedLimitationFlags.has(item))
      )
    ),
  };
}

function buildFaceSchema(source) {
  const glowValue = pickFirstValue([
    source.glow_index,
    source.glowScore,
    source.glow_score,
    source.glow,
    source.energy_score,
    isPlainObject(source.metrics) ? source.metrics.glow : null,
    isPlainObject(source.metrics) ? source.metrics.glowScore : null,
  ]);

  return {
    schema_version: 4,
    scan_type: "face",
    face_score: clampNumber(source.face_score, 0, 100),
    perceived_age: clampNumber(source.perceived_age, 0, 150),
    skin_quality_score: clampNumber(source.skin_quality_score, 0, 100),
    symmetry_percentage: clampNumber(source.symmetry_percentage, 0, 100),
    fatigue_level: clampNumber(source.fatigue_level, 0, 100),
    glow_index: clampNumber(glowValue, 0, 10),
    face_shape: readText(source.face_shape),
    collagen_level: clampNumber(source.collagen_level, 0, 100),
    hydration_level: clampNumber(source.hydration_level, 0, 100),
    photogenic_score: clampNumber(source.photogenic_score, 0, 10),
    skin_clarity_score: clampNumber(source.skin_clarity_score, 0, 100),
    under_eye_shadow_score: clampNumber(source.under_eye_shadow_score, 0, 100),
    under_eye_volume_score: clampNumber(source.under_eye_volume_score, 0, 100),
    eye_openness_score: clampNumber(source.eye_openness_score, 0, 100),
    complexion_redness_score: clampNumber(source.complexion_redness_score, 0, 100),
    pore_visibility_score: clampNumber(source.pore_visibility_score, 0, 100),
    skin_evenness_score: clampNumber(source.skin_evenness_score, 0, 100),
    skin_radiance_score: clampNumber(source.skin_radiance_score, 0, 100),
    lip_dryness_score: clampNumber(source.lip_dryness_score, 0, 100),
    forehead_smoothness_score: clampNumber(source.forehead_smoothness_score, 0, 100),
    t_zone_oiliness_score: clampNumber(source.t_zone_oiliness_score, 0, 100),
    perceived_sex_key: normalizeEnumKey(source.perceived_sex_key, ["male_presenting", "female_presenting", "neutral_or_unclear"]),
    perceived_age_range_key: normalizeEnumKey(source.perceived_age_range_key, ["under_18", "18_24", "25_34", "35_44", "45_54", "55_64", "65_plus"]),
    perceived_stress_level: clampNumber(source.perceived_stress_level, 0, 100),
    perceived_sleep_quality: clampNumber(source.perceived_sleep_quality, 0, 100),
    analysis_meta: buildAnalysisMeta(source),
  };
}

function buildBodySchema(source) {
  return {
    schema_version: 4,
    scan_type: "body",
    body_score: clampNumber(source.body_score, 0, 100),
    body_fat_percentage: clampNumber(source.body_fat_percentage, 0, 100),
    muscle_mass_label: readText(source.muscle_mass_label),
    body_type: readText(source.body_type),
    posture_score: clampNumber(source.posture_score, 0, 10),
    waist_estimation_cm: clampNumber(source.waist_estimation_cm, 0, 300),
    strength_index: clampNumber(source.strength_index, 0, 100),
    body_symmetry: clampNumber(source.body_symmetry, 0, 100),
    bmi_estimate: clampNumber(source.bmi_estimate, 0, 100),
    metabolic_age: clampNumber(source.metabolic_age, 0, 150),
    muscle_definition_score: clampNumber(source.muscle_definition_score, 0, 100),
    midsection_definition_score: clampNumber(source.midsection_definition_score, 0, 100),
    shoulder_alignment_score: clampNumber(source.shoulder_alignment_score, 0, 100),
    recovery_readiness_score: clampNumber(source.recovery_readiness_score, 0, 100),
    upper_body_definition_score: clampNumber(source.upper_body_definition_score, 0, 100),
    lower_body_definition_score: clampNumber(source.lower_body_definition_score, 0, 100),
    arm_definition_score: clampNumber(source.arm_definition_score, 0, 100),
    v_taper_score: clampNumber(source.v_taper_score, 0, 100),
    body_tension_indicator_score: clampNumber(source.body_tension_indicator_score, 0, 100),
    perceived_sex_key: normalizeEnumKey(source.perceived_sex_key, ["male_presenting", "female_presenting", "neutral_or_unclear"]),
    perceived_age_range_key: normalizeEnumKey(source.perceived_age_range_key, ["under_18", "18_24", "25_34", "35_44", "45_54", "55_64", "65_plus"]),
    estimated_height_range_key: normalizeEnumKey(source.estimated_height_range_key, ["under_150cm", "150_160cm", "160_170cm", "170_180cm", "180_190cm", "190_plus"]),
    estimated_weight_range_key: normalizeEnumKey(source.estimated_weight_range_key, ["under_50kg", "50_60kg", "60_70kg", "70_80kg", "80_90kg", "90_100kg", "100_plus"]),
    body_frame_key: normalizeEnumKey(source.body_frame_key, ["small", "medium", "large"]),
    perceived_fitness_level_key: normalizeEnumKey(source.perceived_fitness_level_key, ["sedentary", "lightly_active", "moderately_active", "very_active", "athletic"]),
    analysis_meta: buildAnalysisMeta(source),
  };
}

function buildNutritionSchema(source) {
  return {
    schema_version: 4,
    scan_type: "nutrition",
    plate_health_score: clampNumber(source.plate_health_score, 0, 100),
    calories_estimate: clampNumber(source.calories_estimate, 0, 10000),
    protein_grams: clampNumber(source.protein_grams, 0, 1000),
    carbs_grams: clampNumber(source.carbs_grams, 0, 1000),
    fat_grams: clampNumber(source.fat_grams, 0, 1000),
    glycemic_index_label: readText(source.glycemic_index_label),
    satiety_index: clampNumber(source.satiety_index, 0, 10),
    ingredient_quality: readText(source.ingredient_quality),
    main_vitamins: readText(source.main_vitamins),
    short_verdict: readText(source.short_verdict),
    fiber_grams_estimate: clampNumber(source.fiber_grams_estimate, 0, 100),
    sugar_grams_estimate: clampNumber(source.sugar_grams_estimate, 0, 300),
    processing_level_score: clampNumber(source.processing_level_score, 0, 100),
    hydration_contribution_score: clampNumber(source.hydration_contribution_score, 0, 10),
    sodium_level_score: clampNumber(source.sodium_level_score, 0, 10),
    meal_balance_score: clampNumber(source.meal_balance_score, 0, 100),
    inflammation_index_score: clampNumber(source.inflammation_index_score, 0, 100),
    meal_type_key: normalizeEnumKey(source.meal_type_key, ["breakfast", "lunch", "dinner", "snack", "dessert", "other"]),
    portion_size_key: normalizeEnumKey(source.portion_size_key, ["small", "medium", "large", "oversized"]),
    color_diversity_score: clampNumber(source.color_diversity_score, 0, 10),
    vegetable_portion_ratio: clampNumber(source.vegetable_portion_ratio, 0, 100),
    protein_visibility_score: clampNumber(source.protein_visibility_score, 0, 100),
    whole_grain_indicator_score: clampNumber(source.whole_grain_indicator_score, 0, 100),
    meal_freshness_score: clampNumber(source.meal_freshness_score, 0, 100),
    cuisine_type_key: normalizeEnumKey(source.cuisine_type_key, ["mediterranean", "asian", "western", "middle_eastern", "latin", "african", "mixed", "other"]),
    meat_type_key: normalizeEnumKey(source.meat_type_key, ["red_meat", "poultry", "fish", "seafood", "plant_protein", "dairy", "none"]),
    cooking_method_key: normalizeEnumKey(source.cooking_method_key, ["fried", "baked", "grilled", "raw", "steamed", "boiled", "sauteed", "other"]),
    meal_dietary_pattern_key: normalizeEnumKey(source.meal_dietary_pattern_key, ["omnivore", "vegetarian_compatible", "vegan_compatible", "pescetarian_compatible", "keto_compatible", "mediterranean_compatible", "unclear"]),
    allergen_visibility_keys: normalizeEnumArray(source.allergen_visibility_keys, ["gluten_likely", "dairy_likely", "nuts_likely", "shellfish_likely", "eggs_likely", "soy_likely", "seafood_likely"]),
    analysis_meta: buildAnalysisMeta(source),
  };
}

if (scanType === "error") {
  return wrapResult({
    scan_type: "error",
    message: readText(rawObject.message) || getLocalizedMessage("generic_analysis_error"),
  });
}

if (scanType === "face") {
  return wrapResult(buildFaceSchema(rawObject));
}

if (scanType === "body") {
  return wrapResult(buildBodySchema(rawObject));
}

if (scanType === "nutrition") {
  return wrapResult(buildNutritionSchema(rawObject));
}

return errorResult("invalid_scan_response");
